import hashlib, json, re
from pathlib import Path
from datetime import datetime, timezone
source = Path('products/services/uk-offline-qa-quote/raw/tender-feed.json')
raw = source.read_bytes()
now = datetime.now(timezone.utc)
patterns = {'deliverable': r'\b(data quality|data cleansing|data migration|data matching|reconciliation|catalogu[e]|digitis\w+|digitiz\w+)\b', 'acceptance': r'\b(acceptance|validation|accuracy|completeness|verification|quality assurance)\b', 'pricing_structure': r'\b(lot|separate|standalone|fixed price|unit price)\b'}
rows = []
for release in json.loads(raw).get('releases', [])[:30]:
    tender = release.get('tender') or {}
    end = (tender.get('tenderPeriod') or {}).get('endDate')
    try:
        future = datetime.fromisoformat(end.replace('Z', '+00:00')) > now
    except (AttributeError, TypeError, ValueError):
        future = None
    fields = []
    for record in [tender, *(tender.get('lots') or [])]:
        for field in ('title', 'description'):
            text = record.get(field) or ''
            for label, pattern in patterns.items():
                match = re.search(pattern, text, re.I)
                if match:
                    fields.append({'label': label, 'field': field, 'lot_id': record.get('id') if record is not tender else None, 'excerpt': text[max(0, match.start()-90):match.end()+120]})
    labels = {item['label'] for item in fields}
    score = sum(weight for key, weight in [('deliverable', 4), ('acceptance', 2), ('pricing_structure', 1)] if key in labels)
    rows.append({'release_id': release.get('id'), 'ocid': release.get('ocid'), 'title': tender.get('title'), 'deadline': end, 'future': future, 'status': tender.get('status'), 'score': score, 'signals': fields})
ranked = sorted((row for row in rows if row['future'] is True and row['score'] >= 4), key=lambda row: -row['score'])
result = {'screened_at': now.isoformat(), 'source_sha256': hashlib.sha256(raw).hexdigest(), 'screened': len(rows), 'priority_candidates': ranked[:2], 'inventory': [{key: row[key] for key in ('release_id','title','deadline','future','status','score')} for row in rows], 'limit': 'Text matches prioritize direct notice review only. A lot, keyword or future deadline does not establish separately quotable work or eligibility.'}
out = source.parent.parent / 'director-followup-priority.json'
out.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps({'path': str(out), 'readback': json.loads(out.read_text())['priority_candidates']}, ensure_ascii=False))
